pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value) public {
        // Bound value to avoid out-of-gas issues
        value = bound(value, 0, address(this).balance);

        // Record the depositsCount before the call
        uint256 depositsBefore = c.depositsCount();

        // Drive the sendMoney call (onlyOwner, so we must be owner)
        // Since deployer is owner, we can call directly
        c.sendMoney(target, value);

        // After the call, depositsCount must be >= depositsBefore
        // because in the reference it always increases, and in the mutant it stays the same
        assertTrue(c.depositsCount() >= depositsBefore);
    }
}

