pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Ensure value does not overflow or cause revert due to insufficient balance
        vm.assume(value <= address(c).balance);
        vm.assume(target != address(0));

        // Record depositsCount before call
        uint256 before = c.depositsCount();

        // Perform sequence: send ether to trigger fallback (increases depositsCount)
        (bool successFallback, ) = address(c).call{value: 1 wei}("");
        require(successFallback, "fallback failed");

        // Then call sendMoney
        bool reverted = false;
        try c.sendMoney(target, value) {
            // success
        } catch {
            reverted = true;
        }

        // State after call
        uint256 after = c.depositsCount();

        // General rule: depositsCount never decreases
        assertTrue(after >= before, "depositsCount decreased");
    }
}

