pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Restrict to avoid overflow/underflow issues and ensure the target is not the contract itself
        vm.assume(target != address(c));
        vm.assume(value <= address(c).balance);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Call sendMoney
        c.sendMoney(target, value);

        // After the call, the withdraw() getter (which returns owner's balance) should be >= balanceBefore - value
        // Actually, withdraw() returns the balance of msg.sender (owner), but the invariant is that the contract balance decreased by exactly value
        // Since the buggy version does nothing, the contract balance stays unchanged
        // The rule: the contract balance must decrease by exactly value
        assertTrue(address(c).balance == balanceBefore - value);
    }
}

