pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0));
        vm.assume(value > 0 && value <= address(c).balance);

        // Drive the contract to a state where sendMoney can be called
        // First, deal some ETH to the contract
        address(c).call{value: 1 ether}("");

        // Call sendMoney
        c.sendMoney(target, value);

        // The rule: after sendMoney, c.withdraw() (which returns owner's ETH balance) must be divisible by 1000
        // This is a general invariant that holds in the reference because the withdraw function actually transfers ETH,
        // which changes the owner's balance in steps of at least 1 wei, but the empty body version leaves it unchanged,
        // so the rule will fail on the mutant.
        assertTrue(c.withdraw() % 1000 == 0);
    }
}

